# Define dropout rate and regularization strength
dropout_rate = 0.5
weight_decay = 0.0001

# Data ingestion
DATA_DIR = "/mnt/disks/data/birdclef"
METADATA_FILE = os.path.join(DATA_DIR, "train.csv")
train_loader = get_dataloader(DATA_DIR, METADATA_FILE, batch_size=batch_size)

# Limit training data to 15000 samples
train_subset = torch.utils.data.Subset(train_loader.dataset, range(min(15000, len(train_loader.dataset))))
train_loader = torch.utils.data.DataLoader(train_subset, batch_size=batch_size, shuffle=True)

# Define the model architecture
class BirdCLEFModel(nn.Module):
    def __init__(self, num_species, num_conv_layers, dropout_rate):
        super(BirdCLEFModel, self).__init__()
        conv_layers = []
        in_channels = 1
        
        # Construct convolutional layers
        for i in range(num_conv_layers):
            out_channels = 32 * (i + 1)
            conv_layer = nn.Sequential(
                nn.Conv2d(in_channels, out_channels, kernel_size=3, padding=1),
                nn.BatchNorm2d(out_channels),
                nn.ReLU(),
            )
            conv_layers.append(conv_layer)
            in_channels = out_channels
        
        self.conv_layers = nn.Sequential(*conv_layers)
        self.pool = nn.AdaptiveAvgPool2d((1, 1))
        self.classifier = nn.Sequential(
            nn.Linear(in_channels, 128),
            nn.ReLU(),
            nn.Dropout(dropout_rate),
            nn.Linear(128, num_species)
        )

    def forward(self, x):
        x = self.conv_layers(x)
        x = self.pool(x).view(x.size(0), -1)
        return torch.sigmoid(self.classifier(x))

# Initialize model, loss function, and optimizer
model = BirdCLEFModel(num_species=num_species, num_conv_layers=num_conv_layers, dropout_rate=dropout_rate)
criterion = nn.BCELoss()
optimizer = optim.Adam(model.parameters(), lr=lr, weight_decay=weight_decay)

# Move model to CUDA if available
